double det = 0.0;
// Build 2x2 submatrix by excluding the specified row and column
int sub_i = 0;
for (int i = 0; i < 3; i++) {
    if (i == row) continue;
    int sub_j = 0;
    for (int j = 0; j < 3; j++) {
        if (j == col) continue;
        det += m[i][j] * ((sub_i == 0 && sub_j == 1) || (sub_i == 1 && sub_j == 0) ? -1 : 1);
        sub_j++;
    }
    sub_i++;
}
// Calculate determinant of 2x2 submatrix: ad - bc
double a = m[(row + 1) % 3][(col + 1) % 3];
double b = m[(row + 1) % 3][(col + 2) % 3];
double c = m[(row + 2) % 3][(col + 1) % 3];
double d = m[(row + 2) % 3][(col + 2) % 3];
det = a * d - b * c;
// Apply cofactor sign: (-1)^(row+col)
return ((row + col) % 2 == 0) ? det : -det;

